    seen, out = set(), []
    for t in tasks:
        if t["id"] in seen:
            continue
        seen.add(t["id"])
        out.append(t)
    return out


def render(tasks, now=None):
    tasks = _unique(tasks)
    known = {key for key, _ in COLUMNS}
    for t in tasks:
        if t["status"] not in known:
